parameters.jsCode:
// Validate incoming event
const event = $input.first().json;

// Check required fields
if (!event.id || !event.type || !event.data) {
  throw new Error('Invalid event format');
}

// Verify event type
if (event.type !== 'user.created') {
  throw new Error(`Expected user.created, got ${event.type}`);
}

// Extract user data
const userData = event.data;
if (!userData.user_id || !userData.email) {
  throw new Error('Missing required user data');
}

// Set variables for downstream nodes
$vars.set('eventId', event.id);
$vars.set('userId', userData.user_id);
$vars.set('userEmail', userData.email);
$vars.set('businessName', userData.business_name || '');
$vars.set('correlationId', event.correlation_id || event.id);

return [{
  json: {
    event_id: event.id,
    user_id: userData.user_id,
    email: userData.email,
    business_name: userData.business_name,
    correlation_id: event.correlation_id
  }
}];

// Enrich user data with additional information
const userData = $input.first().json;

// Generate welcome message
const welcomeMessage = userData.business_name 
  ? `Welcome to LightningFlow AI, ${userData.business_name}!`
  : `Welcome to LightningFlow AI!`;

// Set default preferences
const preferences = {
  notifications_enabled: true,
  theme: 'light',
  language: 'en',
  timezone: 'UTC'
};

// Generate onboarding checklist
const checklist = [
  'Complete profile setup',
  'Connect Lightning wallet',
  'Choose AI agents',
  'Set up payment methods',
  'Explore dashboard'
];

return [{
  json: {
    ...userData,
    welcome_message: welcomeMessage,
    preferences,
    onboarding_checklist: checklist,
    enriched_at: new Date().toISOString()
  }
}];

